import * as z from 'zod'

export const AddUploadPartRequestSchema = z.strictObject({
  data: z.file().meta({ description: 'The chunk of bytes for this Part.\n' }),
})

export type AddUploadPartRequestSchema = z.infer<typeof AddUploadPartRequestSchema>

export const AdminApiKeySchema = z
  .object({
    object: z
      .literal('organization.admin_api_key')
      .meta({ description: 'The object type, which is always `organization.admin_api_key`' }),
    id: z
      .string()
      .meta({
        description: 'The identifier, which can be referenced in API endpoints',
        examples: ['key_abc'],
      }),
    name: z
      .union([z.string(), z.null()])
      .meta({ description: 'The name of the API key', examples: ['Administration Key'] })
      .exactOptional(),
    redacted_value: z
      .string()
      .meta({ description: 'The redacted value of the API key', examples: ['sk-admin...def'] }),
    created_at: z
      .int()
      .meta({
        description: 'The Unix timestamp (in seconds) of when the API key was created',
        examples: [1711471533],
      }),
    expires_at: z.union([
      z
        .int()
        .meta({
          description: 'The Unix timestamp (in seconds) of when the API key expires',
          examples: [1714063533],
        }),
      z.null(),
    ]),
    last_used_at: z
      .union([
        z
          .int()
          .meta({
            description: 'The Unix timestamp (in seconds) of when the API key was last used',
            examples: [1711471534],
          }),
        z.null(),
      ])
      .exactOptional(),
    owner: z.object({
      type: z
        .string()
        .meta({ description: 'Always `user`', examples: ['user'] })
        .exactOptional(),
      object: z
        .string()
        .meta({
          description: 'The object type, which is always organization.user',
          examples: ['organization.user'],
        })
        .exactOptional(),
      id: z
        .string()
        .meta({
          description: 'The identifier, which can be referenced in API endpoints',
          examples: ['sa_456'],
        })
        .exactOptional(),
      name: z
        .string()
        .meta({ description: 'The name of the user', examples: ['My Service Account'] })
        .exactOptional(),
      created_at: z
        .int()
        .meta({
          description: 'The Unix timestamp (in seconds) of when the user was created',
          examples: [1711471533],
        })
        .exactOptional(),
      role: z
        .string()
        .meta({ description: 'Always `owner`', examples: ['owner'] })
        .exactOptional(),
    }),
  })
  .meta({ description: 'Represents an individual Admin API key in an org.' })

export type AdminApiKeySchema = z.infer<typeof AdminApiKeySchema>

export const AdminApiKeyCreateResponseSchema = z.intersection(
  AdminApiKeySchema,
  z
    .object({
      value: z
        .string()
        .meta({
          description: 'The value of the API key. Only shown on create.',
          examples: ['sk-admin-1234abcd'],
        }),
    })
    .meta({
      description:
        'The newly created admin API key. The `value` field is only returned once, when the key is created.',
    }),
)

export type AdminApiKeyCreateResponseSchema = z.infer<typeof AdminApiKeyCreateResponseSchema>

export const ApiKeyListSchema = z.object({
  object: z.literal('list').meta({ examples: ['list'] }),
  data: z.array(AdminApiKeySchema),
  has_more: z.boolean().meta({ examples: [false] }),
  first_id: z
    .union([z.string(), z.null()])
    .meta({ examples: ['key_abc'] })
    .exactOptional(),
  last_id: z
    .union([z.string(), z.null()])
    .meta({ examples: ['key_xyz'] })
    .exactOptional(),
})

export type ApiKeyListSchema = z.infer<typeof ApiKeyListSchema>

export const AssignedRoleDetailsSchema = z
  .object({
    id: z.string().meta({ description: 'Identifier for the role.' }),
    name: z.string().meta({ description: 'Name of the role.' }),
    permissions: z.array(z.string()).meta({ description: 'Permissions associated with the role.' }),
    resource_type: z.string().meta({ description: 'Resource type the role applies to.' }),
    predefined_role: z.boolean().meta({ description: 'Whether the role is predefined by OpenAI.' }),
    description: z.union([z.string(), z.null()]).meta({ description: 'Description of the role.' }),
    created_at: z.union([z.int(), z.null()]).meta({ description: 'When the role was created.' }),
    updated_at: z
      .union([z.int(), z.null()])
      .meta({ description: 'When the role was last updated.' }),
    created_by: z
      .union([z.string(), z.null()])
      .meta({ description: 'Identifier of the actor who created the role.' }),
    created_by_user_obj: z
      .union([z.any(), z.null()])
      .meta({ description: 'User details for the actor that created the role, when available.' }),
    metadata: z
      .union([z.any(), z.null()])
      .meta({ description: 'Arbitrary metadata stored on the role.' }),
    assignment_sources: z
      .union([
        z.array(z.object({ principal_id: z.string(), principal_type: z.string() })),
        z.null(),
      ])
      .meta({
        description: 'Principals from which the role assignment is inherited, when available.',
      }),
  })
  .meta({
    description:
      'Detailed information about a role assignment entry returned when listing assignments.',
  })

export type AssignedRoleDetailsSchema = z.infer<typeof AssignedRoleDetailsSchema>

export const AssistantToolsCodeSchema = z.object({
  type: z
    .literal('code_interpreter')
    .meta({ description: 'The type of tool being defined: `code_interpreter`' }),
})

export type AssistantToolsCodeSchema = z.infer<typeof AssistantToolsCodeSchema>

export const FileSearchRankerSchema = z
  .enum(['auto', 'default_2024_08_21'])
  .meta({
    description:
      'The ranker to use for the file search. If not specified will use the `auto` ranker.',
  })

export type FileSearchRankerSchema = z.infer<typeof FileSearchRankerSchema>

export const FileSearchRankingOptionsSchema = z
  .object({
    ranker: FileSearchRankerSchema.exactOptional(),
    score_threshold: z
      .number()
      .min(0)
      .max(1)
      .meta({
        description:
          'The score threshold for the file search. All values must be a floating point number between 0 and 1.',
      }),
  })
  .meta({
    description:
      'The ranking options for the file search. If not specified, the file search tool will use the `auto` ranker and a score_threshold of 0.\n\nSee the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
  })

export type FileSearchRankingOptionsSchema = z.infer<typeof FileSearchRankingOptionsSchema>

export const AssistantToolsFileSearchSchema = z.object({
  type: z
    .literal('file_search')
    .meta({ description: 'The type of tool being defined: `file_search`' }),
  file_search: z
    .object({
      max_num_results: z
        .int()
        .min(1)
        .max(50)
        .meta({
          description:
            'The maximum number of results the file search tool should output. The default is 20 for `gpt-4*` models and 5 for `gpt-3.5-turbo`. This number should be between 1 and 50 inclusive.\n\nNote that the file search tool may output fewer than `max_num_results` results. See the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
        })
        .exactOptional(),
      ranking_options: FileSearchRankingOptionsSchema.exactOptional(),
    })
    .meta({ description: 'Overrides for the file search tool.' })
    .exactOptional(),
})

export type AssistantToolsFileSearchSchema = z.infer<typeof AssistantToolsFileSearchSchema>

export const FunctionParametersSchema = z
  .any()
  .meta({
    description:
      'The parameters the functions accepts, described as a JSON Schema object. See the [guide](https://developers.openai.com/api/docs/guides/function-calling) for examples, and the [JSON Schema reference](https://json-schema.org/understanding-json-schema/) for documentation about the format.\n\nOmitting `parameters` defines a function with an empty parameter list.',
  })

export type FunctionParametersSchema = z.infer<typeof FunctionParametersSchema>

export const FunctionObjectSchema = z.object({
  description: z
    .string()
    .meta({
      description:
        'A description of what the function does, used by the model to choose when and how to call the function.',
    })
    .exactOptional(),
  name: z
    .string()
    .meta({
      description:
        'The name of the function to be called. Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64.',
    }),
  parameters: FunctionParametersSchema.exactOptional(),
  strict: z
    .union([
      z
        .boolean()
        .default(false)
        .meta({
          description:
            'Whether to enable strict schema adherence when generating the function call. If set to true, the model will follow the exact schema defined in the `parameters` field. Only a subset of JSON Schema is supported when `strict` is `true`. Learn more about Structured Outputs in the [function calling guide](https://developers.openai.com/api/docs/guides/function-calling).',
        }),
      z.null(),
    ])
    .exactOptional(),
})

export type FunctionObjectSchema = z.infer<typeof FunctionObjectSchema>

export const AssistantToolsFunctionSchema = z.object({
  type: z.literal('function').meta({ description: 'The type of tool being defined: `function`' }),
  function: FunctionObjectSchema,
})

export type AssistantToolsFunctionSchema = z.infer<typeof AssistantToolsFunctionSchema>

export const MetadataSchema = z.union([
  z
    .record(z.string(), z.string())
    .meta({
      description:
        'Set of 16 key-value pairs that can be attached to an object. This can be\nuseful for storing additional information about the object in a structured\nformat, and querying for objects via API or the dashboard.\n\nKeys are strings with a maximum length of 64 characters. Values are strings\nwith a maximum length of 512 characters.\n',
    }),
  z.null(),
])

export type MetadataSchema = z.infer<typeof MetadataSchema>

export const ResponseFormatTextSchema = z
  .object({
    type: z
      .literal('text')
      .meta({ description: 'The type of response format being defined. Always `text`.' }),
  })
  .meta({ description: 'Default response format. Used to generate text responses.\n' })

export type ResponseFormatTextSchema = z.infer<typeof ResponseFormatTextSchema>

export const ResponseFormatJsonObjectSchema = z
  .object({
    type: z
      .literal('json_object')
      .meta({ description: 'The type of response format being defined. Always `json_object`.' }),
  })
  .meta({
    description:
      'JSON object response format. An older method of generating JSON responses.\nUsing `json_schema` is recommended for models that support it. Note that the\nmodel will not generate JSON without a system or user message instructing it\nto do so.\n',
  })

export type ResponseFormatJsonObjectSchema = z.infer<typeof ResponseFormatJsonObjectSchema>

export const ResponseFormatJsonSchemaSchemaSchema = z
  .any()
  .meta({
    description:
      'The schema for the response format, described as a JSON Schema object.\nLearn how to build JSON schemas [here](https://json-schema.org/).\n',
  })

export type ResponseFormatJsonSchemaSchemaSchema = z.infer<
  typeof ResponseFormatJsonSchemaSchemaSchema
>

export const ResponseFormatJsonSchemaSchema = z
  .object({
    type: z
      .literal('json_schema')
      .meta({ description: 'The type of response format being defined. Always `json_schema`.' }),
    json_schema: z
      .object({
        description: z
          .string()
          .meta({
            description:
              'A description of what the response format is for, used by the model to\ndetermine how to respond in the format.\n',
          })
          .exactOptional(),
        name: z
          .string()
          .meta({
            description:
              'The name of the response format. Must be a-z, A-Z, 0-9, or contain\nunderscores and dashes, with a maximum length of 64.\n',
          }),
        schema: ResponseFormatJsonSchemaSchemaSchema.exactOptional(),
        strict: z
          .union([
            z
              .boolean()
              .default(false)
              .meta({
                description:
                  'Whether to enable strict schema adherence when generating the output.\nIf set to true, the model will always follow the exact schema defined\nin the `schema` field. Only a subset of JSON Schema is supported when\n`strict` is `true`. To learn more, read the [Structured Outputs\nguide](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
              }),
            z.null(),
          ])
          .exactOptional(),
      })
      .meta({
        description: 'Structured Outputs configuration options, including a JSON Schema.\n',
      }),
  })
  .meta({
    description:
      'JSON Schema response format. Used to generate structured JSON responses.\nLearn more about [Structured Outputs](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
  })

export type ResponseFormatJsonSchemaSchema = z.infer<typeof ResponseFormatJsonSchemaSchema>

export const AssistantsApiResponseFormatOptionSchema = z
  .xor([
    z.literal('auto').meta({ description: '`auto` is the default value\n' }),
    ResponseFormatTextSchema,
    ResponseFormatJsonObjectSchema,
    ResponseFormatJsonSchemaSchema,
  ])
  .meta({
    description:
      'Specifies the format that the model must output. Compatible with [GPT-4o](https://developers.openai.com/api/docs/models/gpt-4o), [GPT-4 Turbo](https://developers.openai.com/api/docs/models/gpt-4-turbo), and all GPT-3.5 Turbo models since `gpt-3.5-turbo-1106`.\n\nSetting to `{ "type": "json_schema", "json_schema": {...} }` enables Structured Outputs which ensures the model will match your supplied JSON schema. Learn more in the [Structured Outputs guide](https://developers.openai.com/api/docs/guides/structured-outputs).\n\nSetting to `{ "type": "json_object" }` enables JSON mode, which ensures the message the model generates is valid JSON.\n\n**Important:** when using JSON mode, you **must** also instruct the model to produce JSON yourself via a system or user message. Without this, the model may generate an unending stream of whitespace until the generation reaches the token limit, resulting in a long-running and seemingly "stuck" request. Also note that the message content may be partially cut off if `finish_reason="length"`, which indicates the generation exceeded `max_tokens` or the conversation exceeded the max context length.\n',
  })

export type AssistantsApiResponseFormatOptionSchema = z.infer<
  typeof AssistantsApiResponseFormatOptionSchema
>

export const AssistantObjectSchema = z
  .object({
    id: z
      .string()
      .meta({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: z
      .literal('assistant')
      .meta({ description: 'The object type, which is always `assistant`.' }),
    created_at: z
      .int()
      .meta({ description: 'The Unix timestamp (in seconds) for when the assistant was created.' }),
    name: z.union([
      z
        .string()
        .max(256)
        .meta({
          description: 'The name of the assistant. The maximum length is 256 characters.\n',
        }),
      z.null(),
    ]),
    description: z.union([
      z
        .string()
        .max(512)
        .meta({
          description: 'The description of the assistant. The maximum length is 512 characters.\n',
        }),
      z.null(),
    ]),
    model: z
      .string()
      .meta({
        description:
          'ID of the model to use. You can use the [List models](https://developers.openai.com/api/reference/resources/models/methods/list) API to see all of your available models, or see our [Model overview](https://developers.openai.com/api/docs/models) for descriptions of them.\n',
      }),
    instructions: z.union([
      z
        .string()
        .max(256000)
        .meta({
          description:
            'The system instructions that the assistant uses. The maximum length is 256,000 characters.\n',
        }),
      z.null(),
    ]),
    tools: z
      .array(
        z.xor([
          AssistantToolsCodeSchema,
          AssistantToolsFileSearchSchema,
          AssistantToolsFunctionSchema,
        ]),
      )
      .max(128)
      .default([])
      .meta({
        description:
          'A list of tool enabled on the assistant. There can be a maximum of 128 tools per assistant. Tools can be of types `code_interpreter`, `file_search`, or `function`.\n',
      }),
    tool_resources: z
      .union([
        z
          .object({
            code_interpreter: z
              .object({
                file_ids: z
                  .array(z.string())
                  .max(20)
                  .default([])
                  .meta({
                    description:
                      'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter`` tool. There can be a maximum of 20 files associated with the tool.\n',
                  })
                  .exactOptional(),
              })
              .exactOptional(),
            file_search: z
              .object({
                vector_store_ids: z
                  .array(z.string())
                  .max(1)
                  .meta({
                    description:
                      'The ID of the [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n',
                  })
                  .exactOptional(),
              })
              .exactOptional(),
          })
          .meta({
            description:
              "A set of resources that are used by the assistant's tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
          }),
        z.null(),
      ])
      .exactOptional(),
    metadata: MetadataSchema,
    temperature: z
      .union([
        z
          .number()
          .min(0)
          .max(2)
          .default(1)
          .meta({
            description:
              'What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.\n',
            examples: [1],
          }),
        z.null(),
      ])
      .exactOptional(),
    top_p: z
      .union([
        z
          .number()
          .min(0)
          .max(1)
          .default(1)
          .meta({
            description:
              'An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.\n\nWe generally recommend altering this or temperature but not both.\n',
            examples: [1],
          }),
        z.null(),
      ])
      .exactOptional(),
    response_format: z.union([AssistantsApiResponseFormatOptionSchema, z.null()]).exactOptional(),
  })
  .meta({
    description: 'Represents an `assistant` that can call the model and use tools.',
    deprecated: true,
  })

export type AssistantObjectSchema = z.infer<typeof AssistantObjectSchema>

export const ThreadObjectSchema = z
  .object({
    id: z
      .string()
      .meta({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: z.literal('thread').meta({ description: 'The object type, which is always `thread`.' }),
    created_at: z
      .int()
      .meta({ description: 'The Unix timestamp (in seconds) for when the thread was created.' }),
    tool_resources: z.union([
      z
        .object({
          code_interpreter: z
            .object({
              file_ids: z
                .array(z.string())
                .max(20)
                .default([])
                .meta({
                  description:
                    'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n',
                })
                .exactOptional(),
            })
            .exactOptional(),
          file_search: z
            .object({
              vector_store_ids: z
                .array(z.string())
                .max(1)
                .meta({
                  description:
                    'The [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n',
                })
                .exactOptional(),
            })
            .exactOptional(),
        })
        .meta({
          description:
            "A set of resources that are made available to the assistant's tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
        }),
      z.null(),
    ]),
    metadata: MetadataSchema,
  })
  .meta({
    description:
      'Represents a thread that contains [messages](https://developers.openai.com/api/docs/assistants/migration).',
  })

export type ThreadObjectSchema = z.infer<typeof ThreadObjectSchema>

export const ThreadStreamEventSchema = z.xor([
  z
    .object({
      enabled: z
        .boolean()
        .meta({ description: 'Whether to enable input audio transcription.' })
        .exactOptional(),
      event: z.literal('thread.created'),
      data: ThreadObjectSchema,
    })
    .meta({
      description:
        'Occurs when a new [thread](https://developers.openai.com/api/docs/assistants/migration) is created.',
    }),
])

export type ThreadStreamEventSchema = z.infer<typeof ThreadStreamEventSchema>

export const RunToolCallObjectSchema = z
  .object({
    id: z
      .string()
      .meta({
        description:
          'The ID of the tool call. This ID must be referenced when you submit the tool outputs in using the [Submit tool outputs to run](https://developers.openai.com/api/docs/assistants/migration) endpoint.',
      }),
    type: z
      .literal('function')
      .meta({
        description:
          'The type of tool call the output is required for. For now, this is always `function`.',
      }),
    function: z
      .object({
        name: z.string().meta({ description: 'The name of the function.' }),
        arguments: z
          .string()
          .meta({
            description: 'The arguments that the model expects you to pass to the function.',
          }),
      })
      .meta({ description: 'The function definition.' }),
  })
  .meta({ description: 'Tool call objects' })

export type RunToolCallObjectSchema = z.infer<typeof RunToolCallObjectSchema>

export const RunCompletionUsageSchema = z.union([
  z
    .object({
      completion_tokens: z
        .int()
        .meta({ description: 'Number of completion tokens used over the course of the run.' }),
      prompt_tokens: z
        .int()
        .meta({ description: 'Number of prompt tokens used over the course of the run.' }),
      total_tokens: z
        .int()
        .meta({ description: 'Total number of tokens used (prompt + completion).' }),
    })
    .meta({
      description:
        'Usage statistics related to the run. This value will be `null` if the run is not in a terminal state (i.e. `in_progress`, `queued`, etc.).',
    }),
  z.null(),
])

export type RunCompletionUsageSchema = z.infer<typeof RunCompletionUsageSchema>

export const TruncationObjectSchema = z
  .object({
    type: z
      .enum(['auto', 'last_messages'])
      .meta({
        description:
          'The truncation strategy to use for the thread. The default is `auto`. If set to `last_messages`, the thread will be truncated to the n most recent messages in the thread. When set to `auto`, messages in the middle of the thread will be dropped to fit the context length of the model, `max_prompt_tokens`.',
      }),
    last_messages: z
      .union([
        z
          .int()
          .min(1)
          .meta({
            description:
              'The number of most recent messages from the thread when constructing the context for the run.',
          }),
        z.null(),
      ])
      .exactOptional(),
  })
  .meta({
    description:
      'Controls for how a thread will be truncated prior to the run. Use this to control the initial context window of the run.',
  })

export type TruncationObjectSchema = z.infer<typeof TruncationObjectSchema>

export const AssistantsNamedToolChoiceSchema = z
  .object({
    type: z
      .enum(['function', 'code_interpreter', 'file_search'])
      .meta({
        description: 'The type of the tool. If type is `function`, the function name must be set',
      }),
    function: z
      .object({ name: z.string().meta({ description: 'The name of the function to call.' }) })
      .exactOptional(),
  })
  .meta({
    description:
      'Specifies a tool the model should use. Use to force the model to call a specific tool.',
  })

export type AssistantsNamedToolChoiceSchema = z.infer<typeof AssistantsNamedToolChoiceSchema>

export const AssistantsApiToolChoiceOptionSchema = z
  .xor([
    z
      .enum(['none', 'auto', 'required'])
      .meta({
        description:
          '`none` means the model will not call any tools and instead generates a message. `auto` means the model can pick between generating a message or calling one or more tools. `required` means the model must call one or more tools before responding to the user.\n',
      }),
    AssistantsNamedToolChoiceSchema,
  ])
  .meta({
    description:
      'Controls which (if any) tool is called by the model.\n`none` means the model will not call any tools and instead generates a message.\n`auto` is the default value and means the model can pick between generating a message or calling one or more tools.\n`required` means the model must call one or more tools before responding to the user.\nSpecifying a particular tool like `{"type": "file_search"}` or `{"type": "function", "function": {"name": "my_function"}}` forces the model to call that tool.\n',
  })

export type AssistantsApiToolChoiceOptionSchema = z.infer<
  typeof AssistantsApiToolChoiceOptionSchema
>

export const ParallelToolCallsSchema = z
  .boolean()
  .default(true)
  .meta({
    description:
      'Whether to enable [parallel function calling](https://developers.openai.com/api/docs/guides/function-calling#parallel-function-calling) during tool use.',
  })

export type ParallelToolCallsSchema = z.infer<typeof ParallelToolCallsSchema>

export const RunObjectSchema = z
  .object({
    id: z
      .string()
      .meta({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: z
      .literal('thread.run')
      .meta({ description: 'The object type, which is always `thread.run`.' }),
    created_at: z
      .int()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run was created.' }),
    thread_id: z
      .string()
      .meta({
        description:
          'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was executed on as a part of this run.',
      }),
    assistant_id: z
      .string()
      .meta({
        description:
          'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for execution of this run.',
      }),
    status: z
      .enum([
        'queued',
        'in_progress',
        'requires_action',
        'cancelling',
        'cancelled',
        'failed',
        'completed',
        'incomplete',
        'expired',
      ])
      .meta({
        description:
          'The status of the run, which can be either `queued`, `in_progress`, `requires_action`, `cancelling`, `cancelled`, `failed`, `completed`, `incomplete`, or `expired`.',
      }),
    required_action: z
      .object({
        type: z
          .literal('submit_tool_outputs')
          .meta({ description: 'For now, this is always `submit_tool_outputs`.' }),
        submit_tool_outputs: z
          .object({
            tool_calls: z
              .array(RunToolCallObjectSchema)
              .meta({ description: 'A list of the relevant tool calls.' }),
          })
          .meta({ description: 'Details on the tool outputs needed for this run to continue.' }),
      })
      .nullable()
      .meta({
        description:
          'Details on the action required to continue the run. Will be `null` if no action is required.',
      }),
    last_error: z
      .object({
        code: z
          .enum(['server_error', 'rate_limit_exceeded', 'invalid_prompt'])
          .meta({
            description: 'One of `server_error`, `rate_limit_exceeded`, or `invalid_prompt`.',
          }),
        message: z.string().meta({ description: 'A human-readable description of the error.' }),
      })
      .nullable()
      .meta({
        description:
          'The last error associated with this run. Will be `null` if there are no errors.',
      }),
    expires_at: z
      .int()
      .nullable()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run will expire.' }),
    started_at: z
      .int()
      .nullable()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run was started.' }),
    cancelled_at: z
      .int()
      .nullable()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run was cancelled.' }),
    failed_at: z
      .int()
      .nullable()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run failed.' }),
    completed_at: z
      .int()
      .nullable()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run was completed.' }),
    incomplete_details: z
      .object({
        reason: z
          .enum(['max_completion_tokens', 'max_prompt_tokens'])
          .meta({
            description:
              'The reason why the run is incomplete. This will point to which specific token limit was reached over the course of the run.',
          })
          .exactOptional(),
      })
      .nullable()
      .meta({
        description:
          'Details on why the run is incomplete. Will be `null` if the run is not incomplete.',
      }),
    model: z
      .string()
      .meta({
        description:
          'The model that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      }),
    instructions: z
      .string()
      .meta({
        description:
          'The instructions that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      }),
    tools: z
      .array(
        z.xor([
          AssistantToolsCodeSchema,
          AssistantToolsFileSearchSchema,
          AssistantToolsFunctionSchema,
        ]),
      )
      .max(20)
      .default([])
      .meta({
        description:
          'The list of tools that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      }),
    metadata: MetadataSchema,
    usage: RunCompletionUsageSchema,
    temperature: z
      .number()
      .nullable()
      .meta({
        description: 'The sampling temperature used for this run. If not set, defaults to 1.',
      })
      .exactOptional(),
    top_p: z
      .number()
      .nullable()
      .meta({
        description: 'The nucleus sampling value used for this run. If not set, defaults to 1.',
      })
      .exactOptional(),
    max_prompt_tokens: z
      .int()
      .min(256)
      .nullable()
      .meta({
        description:
          'The maximum number of prompt tokens specified to have been used over the course of the run.\n',
      }),
    max_completion_tokens: z
      .int()
      .min(256)
      .nullable()
      .meta({
        description:
          'The maximum number of completion tokens specified to have been used over the course of the run.\n',
      }),
    truncation_strategy: z.union([TruncationObjectSchema, z.null()]),
    tool_choice: z.union([AssistantsApiToolChoiceOptionSchema, z.null()]),
    parallel_tool_calls: ParallelToolCallsSchema,
    response_format: z.union([AssistantsApiResponseFormatOptionSchema, z.null()]),
  })
  .meta({
    description:
      'Represents an execution run on a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  })

export type RunObjectSchema = z.infer<typeof RunObjectSchema>

