export const RunStepObjectSchema = z
  .object({
    id: z
      .string()
      .meta({
        description: 'The identifier of the run step, which can be referenced in API endpoints.',
      }),
    object: z
      .literal('thread.run.step')
      .meta({ description: 'The object type, which is always `thread.run.step`.' }),
    created_at: z
      .int()
      .meta({ description: 'The Unix timestamp (in seconds) for when the run step was created.' }),
    assistant_id: z
      .string()
      .meta({
        description:
          'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) associated with the run step.',
      }),
    thread_id: z
      .string()
      .meta({
        description:
          'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was run.',
      }),
    run_id: z
      .string()
      .meta({
        description:
          'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) that this run step is a part of.',
      }),
    type: z
      .enum(['message_creation', 'tool_calls'])
      .meta({
        description:
          'The type of run step, which can be either `message_creation` or `tool_calls`.',
      }),
    status: z
      .enum(['in_progress', 'cancelled', 'failed', 'completed', 'expired'])
      .meta({
        description:
          'The status of the run step, which can be either `in_progress`, `cancelled`, `failed`, `completed`, or `expired`.',
      }),
    step_details: z
      .xor([RunStepDetailsMessageCreationObjectSchema, RunStepDetailsToolCallsObjectSchema])
      .meta({ description: 'The details of the run step.' }),
    last_error: z.union([
      z
        .object({
          code: z
            .enum(['server_error', 'rate_limit_exceeded'])
            .meta({ description: 'One of `server_error` or `rate_limit_exceeded`.' }),
          message: z.string().meta({ description: 'A human-readable description of the error.' }),
        })
        .meta({
          description:
            'The last error associated with this run step. Will be `null` if there are no errors.',
        }),
      z.null(),
    ]),
    expired_at: z.union([
      z
        .int()
        .meta({
          description:
            'The Unix timestamp (in seconds) for when the run step expired. A step is considered expired if the parent run is expired.',
        }),
      z.null(),
    ]),
    cancelled_at: z.union([
      z
        .int()
        .meta({
          description: 'The Unix timestamp (in seconds) for when the run step was cancelled.',
        }),
      z.null(),
    ]),
    failed_at: z.union([
      z
        .int()
        .meta({ description: 'The Unix timestamp (in seconds) for when the run step failed.' }),
      z.null(),
    ]),
    completed_at: z.union([
      z
        .int()
        .meta({ description: 'The Unix timestamp (in seconds) for when the run step completed.' }),
      z.null(),
    ]),
    metadata: MetadataSchema,
    usage: RunStepCompletionUsageSchema,
  })
  .meta({ description: 'Represents a step in execution of a run.\n' })

