export const MessageObjectSchema = z
  .object({
    id: z
      .string()
      .meta({ description: 'The identifier, which can be referenced in API endpoints.' }),
    object: z
      .literal('thread.message')
      .meta({ description: 'The object type, which is always `thread.message`.' }),
    created_at: z
      .int()
      .meta({ description: 'The Unix timestamp (in seconds) for when the message was created.' }),
    thread_id: z
      .string()
      .meta({
        description:
          'The [thread](https://developers.openai.com/api/docs/assistants/migration) ID that this message belongs to.',
      }),
    status: z
      .enum(['in_progress', 'incomplete', 'completed'])
      .meta({
        description:
          'The status of the message, which can be either `in_progress`, `incomplete`, or `completed`.',
      }),
    incomplete_details: z.union([
      z
        .object({
          reason: z
            .enum(['content_filter', 'max_tokens', 'run_cancelled', 'run_expired', 'run_failed'])
            .meta({ description: 'The reason the message is incomplete.' }),
        })
        .meta({
          description: 'On an incomplete message, details about why the message is incomplete.',
        }),
      z.null(),
    ]),
    completed_at: z.union([
      z
        .int()
        .meta({
          description: 'The Unix timestamp (in seconds) for when the message was completed.',
        }),
      z.null(),
    ]),
    incomplete_at: z.union([
      z
        .int()
        .meta({
          description:
            'The Unix timestamp (in seconds) for when the message was marked as incomplete.',
        }),
      z.null(),
    ]),
    role: z
      .enum(['user', 'assistant'])
      .meta({ description: 'The entity that produced the message. One of `user` or `assistant`.' }),
    content: z
      .array(
        z.xor([
          MessageContentImageFileObjectSchema,
          MessageContentImageUrlObjectSchema,
          MessageContentTextObjectSchema,
          MessageContentRefusalObjectSchema,
        ]),
      )
      .meta({ description: 'The content of the message in array of text and/or images.' }),
    assistant_id: z.union([
      z
        .string()
        .meta({
          description:
            'If applicable, the ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) that authored this message.',
        }),
      z.null(),
    ]),
    run_id: z.union([
      z
        .string()
        .meta({
          description:
            'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) associated with the creation of this message. Value is `null` when messages are created manually using the create message or create thread endpoints.',
        }),
      z.null(),
    ]),
    attachments: z.union([
      z
        .array(
          z.object({
            file_id: z
              .string()
              .meta({ description: 'The ID of the file to attach to the message.' })
              .exactOptional(),
            tools: z
              .array(z.xor([AssistantToolsCodeSchema, AssistantToolsFileSearchTypeOnlySchema]))
              .meta({ description: 'The tools to add this file to.' })
              .exactOptional(),
          }),
        )
        .meta({
          description: 'A list of files attached to the message, and the tools they were added to.',
        }),
      z.null(),
    ]),
    metadata: MetadataSchema,
  })
  .meta({
    description:
      'Represents a message within a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  })

export type MessageObjectSchema = z.infer<typeof MessageObjectSchema>

