export const AudioTranscriptionResponseSchema = z.object({
  model: z
    .union([
      z.string(),
      z.enum([
        'whisper-1',
        'gpt-transcribe',
        'gpt-live-transcribe',
        'gpt-4o-mini-transcribe',
        'gpt-4o-mini-transcribe-2025-12-15',
        'gpt-4o-transcribe',
        'gpt-4o-transcribe-diarize',
        'gpt-realtime-whisper',
      ]),
    ])
    .meta({
      description:
        'The model used for transcription. Current options are `whisper-1`, `gpt-transcribe`, `gpt-live-transcribe`, `gpt-4o-mini-transcribe`, `gpt-4o-mini-transcribe-2025-12-15`, `gpt-4o-transcribe`, `gpt-4o-transcribe-diarize`, and `gpt-realtime-whisper`.\n',
      examples: ['gpt-transcribe'],
    })
    .exactOptional(),
  language: z
    .string()
    .nullable()
    .meta({ description: 'The language of the input audio.\n' })
    .exactOptional(),
  languages: z
    .array(z.string())
    .min(1)
    .meta({
      description:
        'The possible input audio languages configured for transcription, in [ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes) format.\n',
    })
    .exactOptional(),
  keywords: z
    .array(z.string())
    .meta({
      description: 'Words or phrases configured to guide transcription of the input audio.\n',
    })
    .exactOptional(),
  prompt: z
    .string()
    .meta({ description: 'The prompt configured for input audio transcription, when present.\n' })
    .exactOptional(),
})

export type AudioTranscriptionResponseSchema = z.infer<typeof AudioTranscriptionResponseSchema>

