type CompoundFilterType = {
  type: 'and' | 'or'
  filters: (z.infer<typeof ComparisonFilterSchema> | CompoundFilterType)[]
}

export const CompoundFilterSchema: z.ZodType<CompoundFilterType> = z
  .strictObject({
    type: z.enum(['and', 'or']).meta({ description: 'Type of operation: `and` or `or`.' }),
    filters: z
      .array(
        z.xor([
          z.intersection(ComparisonFilterSchema, z.object({ type: z.literal('ComparisonFilter') })),
          z.intersection(
            z.lazy(() => CompoundFilterSchema),
            z.object({ type: z.literal('CompoundFilter') }),
          ),
        ]),
      )
      .meta({
        description:
          'Array of filters to combine. Items can be `ComparisonFilter` or `CompoundFilter`.',
      }),
  })
  .meta({ description: 'Combine multiple filters using `and` or `or`.' })

export type CompoundFilterSchema = z.infer<typeof CompoundFilterSchema>

