export const ContainerAutoParamSchema = z.object({
  type: z
    .literal('container_auto')
    .default('container_auto')
    .meta({ description: 'Automatically creates a container for this request' }),
  file_ids: z
    .array(z.string().meta({ examples: ['file-123'] }))
    .max(50)
    .meta({ description: 'An optional list of uploaded files to make available to your code.' })
    .exactOptional(),
  memory_limit: z
    .union([
      ContainerMemoryLimitSchema.meta({ description: 'The memory limit for the container.' }),
      z.null(),
    ])
    .exactOptional(),
  network_policy: z
    .xor([
      z.intersection(
        ContainerNetworkPolicyDisabledParamSchema,
        z.object({ type: z.literal('ContainerNetworkPolicyDisabledParam') }),
      ),
      z.intersection(
        ContainerNetworkPolicyAllowlistParamSchema,
        z.object({ type: z.literal('ContainerNetworkPolicyAllowlistParam') }),
      ),
    ])
    .meta({ description: 'Network access policy for the container.' })
    .exactOptional(),
  skills: z
    .array(
      z.xor([
        z.intersection(
          SkillReferenceParamSchema,
          z.object({ type: z.literal('SkillReferenceParam') }),
        ),
        z.intersection(InlineSkillParamSchema, z.object({ type: z.literal('InlineSkillParam') })),
      ]),
    )
    .max(200)
    .meta({
      description:
        'An optional list of skills referenced by id or inline data. Across all inline skills in this list, decoded ZIP data must total at most 50 MiB and Base64 text must total at most 70,254,592 characters, including line breaks. Skill references do not count toward these limits.',
    })
    .exactOptional(),
})

export type ContainerAutoParamSchema = z.infer<typeof ContainerAutoParamSchema>

export const LocalSkillParamSchema = z.object({
  name: z.string().meta({ description: 'The name of the skill.' }),
  description: z.string().meta({ description: 'The description of the skill.' }),
  path: z.string().meta({ description: 'The path to the directory containing the skill.' }),
})

export type LocalSkillParamSchema = z.infer<typeof LocalSkillParamSchema>

export const LocalEnvironmentParamSchema = z.object({
  type: z
    .literal('local')
    .default('local')
    .meta({ description: 'Use a local computer environment.' }),
  skills: z
    .array(LocalSkillParamSchema)
    .max(200)
    .meta({ description: 'An optional list of skills.' })
    .exactOptional(),
})

export type LocalEnvironmentParamSchema = z.infer<typeof LocalEnvironmentParamSchema>

export const ContainerReferenceParamSchema = z.object({
  type: z
    .literal('container_reference')
    .default('container_reference')
    .meta({ description: 'References a container created with the /v1/containers endpoint' }),
  container_id: z
    .string()
    .meta({ description: 'The ID of the referenced container.', examples: ['cntr_123'] }),
})

export type ContainerReferenceParamSchema = z.infer<typeof ContainerReferenceParamSchema>

export const FunctionShellToolParamSchema = z
  .object({
    type: z
      .literal('shell')
      .default('shell')
      .meta({ description: 'The type of the shell tool. Always `shell`.' }),
    environment: z
      .union([
        z.xor([
          z.intersection(
            ContainerAutoParamSchema,
            z.object({ type: z.literal('ContainerAutoParam') }),
          ),
          z.intersection(
            LocalEnvironmentParamSchema,
            z.object({ type: z.literal('LocalEnvironmentParam') }),
          ),
          z.intersection(
            ContainerReferenceParamSchema,
            z.object({ type: z.literal('ContainerReferenceParam') }),
          ),
        ]),
        z.null(),
      ])
      .exactOptional(),
    allowed_callers: z
      .union([
        z
          .array(CallableToolAllowedCallerSchema)
          .min(1)
          .meta({ description: 'The tool invocation context(s).' }),
        z.null(),
      ])
      .exactOptional(),
  })
  .meta({ description: 'A tool that allows the model to execute shell commands.' })

export type FunctionShellToolParamSchema = z.infer<typeof FunctionShellToolParamSchema>

