export const ReasoningEffortSchema = z.union([
  z
    .enum(['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'])
    .default('medium')
    .meta({
      description:
        'Constrains effort on reasoning for reasoning models. Currently supported\nvalues are `none`, `minimal`, `low`, `medium`, `high`, `xhigh`, and `max`.\nReducing reasoning effort can result in faster responses and fewer tokens\nused on reasoning in a response. Not all reasoning models support every\nvalue. See the\n[reasoning guide](https://developers.openai.com/api/docs/guides/reasoning)\nfor model-specific support.\n',
    }),
  z.null(),
])

export type ReasoningEffortSchema = z.infer<typeof ReasoningEffortSchema>

export const TextResponseFormatJsonSchemaSchema = z
  .object({
    type: z
      .literal('json_schema')
      .meta({ description: 'The type of response format being defined. Always `json_schema`.' }),
    description: z
      .string()
      .meta({
        description:
          'A description of what the response format is for, used by the model to\ndetermine how to respond in the format.\n',
      })
      .exactOptional(),
    name: z
      .string()
      .meta({
        description:
          'The name of the response format. Must be a-z, A-Z, 0-9, or contain\nunderscores and dashes, with a maximum length of 64.\n',
      }),
    schema: ResponseFormatJsonSchemaSchemaSchema,
    strict: z
      .union([
        z
          .boolean()
          .default(false)
          .meta({
            description:
              'Whether to enable strict schema adherence when generating the output.\nIf set to true, the model will always follow the exact schema defined\nin the `schema` field. Only a subset of JSON Schema is supported when\n`strict` is `true`. To learn more, read the [Structured Outputs\nguide](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
          }),
        z.null(),
      ])
      .exactOptional(),
  })
  .meta({
    description:
      'JSON Schema response format. Used to generate structured JSON responses.\nLearn more about [Structured Outputs](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
  })

export type TextResponseFormatJsonSchemaSchema = z.infer<typeof TextResponseFormatJsonSchemaSchema>

export const ResponseConfigurationUpdateSchema = z
  .object({
    id: z
      .string()
      .meta({
        description: 'The unique ID of the configuration update item.',
        examples: ['cnfu_123'],
      }),
    type: z
      .literal('configuration_update')
      .default('configuration_update')
      .meta({ description: 'The item type. Always `configuration_update`.' }),
    reasoning: z
      .object({
        effort: ReasoningEffortSchema.meta({
          description:
            'The reasoning effort used for subsequent responses until another\nconfiguration update replaces it.\n',
        }).exactOptional(),
      })
      .meta({ description: 'The reasoning configuration applied by this update.' })
      .exactOptional(),
    text: z
      .object({
        format: z
          .xor([
            z.intersection(
              ResponseFormatTextSchema,
              z.object({ type: z.literal('ResponseFormatText') }),
            ),
            z.intersection(
              TextResponseFormatJsonSchemaSchema,
              z.object({ type: z.literal('TextResponseFormatJsonSchema') }),
            ),
          ])
          .meta({
            description: 'Use a JSON schema for structured output or text to return to plain text.',
          }),
      })
      .meta({ description: 'The text output configuration for subsequent responses.' })
      .exactOptional(),
  })
  .meta({
    description:
      'A configuration update for subsequent responses. Each setting stays in effect\nuntil a later update replaces that setting.\n',
  })

export type ResponseConfigurationUpdateSchema = z.infer<typeof ResponseConfigurationUpdateSchema>

export const ReasoningItemSchema = z
  .object({
    type: z
      .literal('reasoning')
      .meta({ description: 'The type of the object. Always `reasoning`.\n' }),
    id: z.string().meta({ description: 'The unique identifier of the reasoning content.\n' }),
    encrypted_content: z
      .union([
        z
          .string()
          .meta({
            description:
              'The encrypted content of the reasoning item. This is populated by default\nfor reasoning items returned by `POST /v1/responses` and WebSocket\n`response.create` requests.\n\nWhen streaming, use the completed reasoning item and its\n`encrypted_content` from the `response.output_item.done` event in\nsubsequent requests. The `encrypted_content` in\n`response.output_item.added` may be incomplete. This is especially\nimportant when `store` is `false` or when using Zero Data Retention.\n',
          }),
        z.null(),
      ])
      .exactOptional(),
    summary: z
      .array(SummaryTextContentSchema)
      .meta({ description: 'Reasoning summary content.\n' }),
    content: z
      .array(ReasoningTextContentSchema)
      .meta({ description: 'Reasoning text content.\n' })
      .exactOptional(),
    status: z
      .enum(['in_progress', 'completed', 'incomplete'])
      .meta({
        description:
          'The status of the item. One of `in_progress`, `completed`, or\n`incomplete`. Populated when items are returned via API.\n',
      })
      .exactOptional(),
  })
  .meta({
    description:
      'A description of the chain of thought used by a reasoning model while generating\na response. Be sure to include these items in your `input` to the Responses API\nfor subsequent turns of a conversation if you are manually\n[managing context](https://developers.openai.com/api/docs/guides/conversation-state).\n',
  })

export type ReasoningItemSchema = z.infer<typeof ReasoningItemSchema>

