export type PredictionContentSchema = z.infer<typeof PredictionContentSchema>

export const CustomToolChatCompletionsSchema = z
  .object({
    type: z
      .literal('custom')
      .meta({ description: 'The type of the custom tool. Always `custom`.' }),
    custom: z
      .object({
        name: z
          .string()
          .meta({ description: 'The name of the custom tool, used to identify it in tool calls.' }),
        description: z
          .string()
          .meta({
            description: 'Optional description of the custom tool, used to provide more context.\n',
          })
          .exactOptional(),
        format: z
          .xor([
            z
              .strictObject({
                type: z
                  .literal('text')
                  .meta({ description: 'Unconstrained text format. Always `text`.' }),
              })
              .meta({ description: 'Unconstrained free-form text.' }),
            z
              .strictObject({
                type: z
                  .literal('grammar')
                  .meta({ description: 'Grammar format. Always `grammar`.' }),
                grammar: z
                  .object({
                    definition: z.string().meta({ description: 'The grammar definition.' }),
                    syntax: z
                      .enum(['lark', 'regex'])
                      .meta({
                        description:
                          'The syntax of the grammar definition. One of `lark` or `regex`.',
                      }),
                  })
                  .meta({ description: 'Your chosen grammar.' }),
              })
              .meta({ description: 'A grammar defined by the user.' }),
          ])
          .meta({
            description: 'The input format for the custom tool. Default is unconstrained text.\n',
          })
          .exactOptional(),
      })
      .meta({ description: 'Properties of the custom tool.\n' }),
  })
  .meta({ description: 'A custom tool that processes input using a specified format.\n' })

export type CustomToolChatCompletionsSchema = z.infer<typeof CustomToolChatCompletionsSchema>

