export const LiveSIPTransportSchema = z
  .strictObject({
    type: z
      .literal('sip')
      .meta({ description: 'The transport used for the Live session. Always `sip`.' }),
    destination: z
      .string()
      .regex(/^\+[1-9][0-9]{1,14}$/)
      .meta({
        description:
          'Phone number to call in E.164 format. SIP URI destinations are not supported.',
        examples: ['+14155550123'],
      }),
    trunk: LiveSIPTrunkSchema,
  })
  .meta({
    description:
      "Place an outbound SIP call using your provider's trunk. The trunk must support TLS signaling, Opus audio, and SDES-SRTP media. See [Telephony and SIP](https://developers.openai.com/api/docs/guides/voice-sip?api=live#place-an-outbound-call).",
  })

export type LiveSIPTransportSchema = z.infer<typeof LiveSIPTransportSchema>

export const LiveSessionCreateRequestSchema = z
  .strictObject({
    session: LiveMediaSessionCreateParamsSchema.meta({
      description: 'Startup configuration for the Live session.',
    }),
    transport: z
      .xor([
        z.intersection(
          LiveWebRTCTransportSchema,
          z.object({ type: z.literal('LiveWebRTCTransport') }),
        ),
        z.intersection(LiveSIPTransportSchema, z.object({ type: z.literal('LiveSIPTransport') })),
      ])
      .meta({
        description:
          'WebRTC transport with an SDP offer, or SIP transport with a destination and per-call trunk credentials.',
      }),
  })
  .meta({
    description:
      'Create a Live session with a WebRTC SDP offer or place an outbound SIP call. Follow the [Live prompting guide](https://developers.openai.com/api/docs/guides/live-prompting) before choosing frontend and backend instructions. The request starts the session; do not send session.start again on the data channel or sideband.',
  })

export type LiveSessionCreateRequestSchema = z.infer<typeof LiveSessionCreateRequestSchema>

export const SessionSchema = z
  .object({
    id: z
      .string()
      .meta({
        description:
          'Opaque session identifier. Preserve the returned value unchanged, including its prefix.',
      }),
  })
  .meta({
    description:
      'The newly created Live session. Use its ID for session controls and sideband connections.',
  })

export type SessionSchema = z.infer<typeof SessionSchema>

export const LiveSessionCreateResponseSchema = z
  .object({
    session: SessionSchema,
    transport: z
      .xor([
        z.intersection(
          LiveWebRTCTransportSchema,
          z.object({ type: z.literal('LiveWebRTCTransport') }),
        ),
        z
          .object({
            type: z
              .literal('sip')
              .meta({ description: 'The transport used for the Live session. Always `sip`.' }),
          })
          .meta({ description: 'The SIP transport. Trunk credentials and SDP are not returned.' }),
      ])
      .meta({
        description:
          'WebRTC transport with an SDP answer, or SIP transport without SDP or trunk credentials. For SIP, attach a sideband using session.id to receive transport.ringing, transport.answered, and transport.failed notifications.',
      }),
  })
  .meta({
    description:
      'The created Live session and its transport. WebRTC creation returns 201 Created with an SDP answer. Outbound SIP creation returns 201 Created after initialization, before the callee necessarily answers, without SDP or trunk credentials.',
  })

export type LiveSessionCreateResponseSchema = z.infer<typeof LiveSessionCreateResponseSchema>

export const LiveTransportDTMFSendParamSchema = z
  .object({
    event_id: z
      .union([
        z
          .string()
          .max(512)
          .meta({
            description:
              "Optional client identifier for correlating this command with a server event's client_event_id or error.client_event_id.",
          }),
        z.null(),
      ])
      .exactOptional(),
    type: z.literal('transport.dtmf.send').default('transport.dtmf.send'),
    event: z
      .string()
      .regex(/^[0-9A-D*#]$/)
      .length(1)
      .meta({ description: 'The DTMF key to send: one of `0`–`9`, `A`–`D`, `*`, or `#`.' }),
  })
  .meta({
    description:
      'Send one DTMF keypress to the SIP trunk through a Live sideband connection. This command is supported only for SIP calls. A successful send emits `transport.dtmf.sent` on sideband. If you provide `event_id`, the success notification includes it as `client_event_id`; a failure includes it as `error.client_event_id`. Send separate events for multiple keypresses.',
    examples: [{ type: 'transport.dtmf.send', event_id: 'evt_dtmf_001', event: '#' }],
  })

export type LiveTransportDTMFSendParamSchema = z.infer<typeof LiveTransportDTMFSendParamSchema>

