export const RealtimeResponseCreateParamsSchema = z
  .object({
    output_modalities: z
      .array(z.enum(['text', 'audio']))
      .meta({
        description:
          'The set of modalities the model used to respond, currently the only possible values are\n`[\\"audio\\"]`, `[\\"text\\"]`. Audio output always include a text transcript. Setting the\noutput to mode `text` will disable audio output from the model.\n',
      })
      .exactOptional(),
    instructions: z
      .string()
      .meta({
        description:
          'The default system instructions (i.e. system message) prepended to model calls. This field allows the client to guide the model on desired responses. The model can be instructed on response content and format, (e.g. "be extremely succinct", "act friendly", "here are examples of good responses") and on audio behavior (e.g. "talk quickly", "inject emotion into your voice", "laugh frequently"). The instructions are not guaranteed to be followed by the model, but they provide guidance to the model on the desired behavior.\nNote that the server sets default instructions which will be used if this field is not set and are visible in the `session.created` event at the start of the session.\n',
      })
      .exactOptional(),
    audio: z
      .object({
        output: z
          .object({
            format: RealtimeAudioFormatsSchema.meta({
              description: 'The format of the output audio.',
            }).exactOptional(),
            voice: VoiceIdsOrCustomVoiceSchema.default('alloy')
              .meta({
                description:
                  'The voice the model uses to respond. Supported built-in voices are\n`alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`, `shimmer`, `verse`,\n`marin`, and `cedar`. You may also provide a custom voice object with\nan `id`, for example `{ "id": "voice_1234" }`. Voice cannot be changed\nduring the session once the model has responded with audio at least once.\nCustom voices must be created from audio samples. Voices created from text prompts are supported only in Live.\nWe recommend `marin` and `cedar` for best quality.\n',
              })
              .exactOptional(),
          })
          .exactOptional(),
      })
      .meta({ description: 'Configuration for audio input and output.' })
      .exactOptional(),
    tools: z
      .array(z.xor([RealtimeFunctionToolSchema, MCPToolSchema]))
      .meta({ description: 'Tools available to the model.' })
      .exactOptional(),
    tool_choice: z
      .xor([ToolChoiceOptionsSchema, ToolChoiceFunctionSchema, ToolChoiceMCPSchema])
      .default('auto')
      .meta({
        description:
          'How the model chooses tools. Provide one of the string modes or force a specific\nfunction/MCP tool.\n',
      })
      .exactOptional(),
    parallel_tool_calls: z
      .boolean()
      .meta({
        description:
          'Whether the model may call multiple tools in parallel. Only supported by\nreasoning Realtime models such as `gpt-realtime-2`.\n',
      })
      .exactOptional(),
    reasoning: RealtimeReasoningSchema.exactOptional(),
    max_output_tokens: z
      .xor([z.int(), z.literal('inf')])
      .meta({
        description:
          'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls. Provide an integer between 1 and 4096 to\nlimit output tokens, or `inf` for the maximum available tokens for a\ngiven model. Defaults to `inf`.\n',
      })
      .exactOptional(),
    conversation: z
      .xor([z.string(), z.enum(['auto', 'none']).default('auto')])
      .meta({
        description:
          'Controls which conversation the response is added to. Currently supports\n`auto` and `none`, with `auto` as the default value. The `auto` value\nmeans that the contents of the response will be added to the default\nconversation. Set this to `none` to create an out-of-band response which\nwill not add items to default conversation.\n',
      })
      .exactOptional(),
    metadata: MetadataSchema.exactOptional(),
    prompt: PromptSchema.exactOptional(),
    input: z
      .array(RealtimeResponseInputItemSchema)
      .meta({
        description:
          'Input items to include in the prompt for the model. Using this field\ncreates a new context for this Response instead of using the default\nconversation. An empty array `[]` will clear the context for this Response.\nNote that this can include references to items that previously appeared in the session\nusing their id.\n',
      })
      .exactOptional(),
  })
  .meta({ description: 'Create a new Realtime response with these parameters' })

export type RealtimeResponseCreateParamsSchema = z.infer<typeof RealtimeResponseCreateParamsSchema>

export const RealtimeClientEventResponseCreateSchema = z
  .object({
    event_id: z
      .string()
      .max(512)
      .meta({ description: 'Optional client-generated ID used to identify this event.' })
      .exactOptional(),
    type: z
      .literal('response.create')
      .meta({ description: 'The event type, must be `response.create`.' }),
    response: RealtimeResponseCreateParamsSchema.exactOptional(),
  })
  .meta({
    description:
      "This event instructs the server to create a Response, which means triggering \nmodel inference. When in Server VAD mode, the server will create Responses \nautomatically.\n\nA Response will include at least one Item, and may have two, in which case \nthe second will be a function call. These Items will be appended to the \nconversation history by default.\n\nThe server will respond with a `response.created` event, events for Items \nand content created, and finally a `response.done` event to indicate the \nResponse is complete.\n\nThe `response.create` event includes inference configuration like \n`instructions` and `tools`. If these are set, they will override the Session's \nconfiguration for this Response only.\n\nResponses can be created out-of-band of the default Conversation, meaning that they can\nhave arbitrary input, and it's possible to disable writing the output to the Conversation.\nOnly one Response can write to the default Conversation at a time, but otherwise multiple\nResponses can be created in parallel. The `metadata` field is a good way to disambiguate\nmultiple simultaneous Responses.\n\nClients can set `conversation` to `none` to create a Response that does not write to the default\nConversation. Arbitrary input can be provided with the `input` field, which is an array accepting\nraw Items and references to existing Items.\n",
  })

export type RealtimeClientEventResponseCreateSchema = z.infer<
  typeof RealtimeClientEventResponseCreateSchema
>

export const RealtimeTranscriptionSessionCreateRequestGASchema = z
  .object({
    type: z
      .literal('transcription')
      .meta({
        description:
          'The type of session to create. Always `transcription` for transcription sessions.\n',
      }),
    audio: z
      .object({
        input: z
          .object({
            format: RealtimeAudioFormatsSchema.exactOptional(),
            transcription: AudioTranscriptionSchema.meta({
              description:
                'Configuration for input audio transcription, defaults to off and can be set to `null` to turn off once on. Input audio transcription is not native to the model, since the model consumes audio directly. Transcription runs asynchronously through [the /audio/transcriptions endpoint](https://developers.openai.com/api/reference/resources/audio/subresources/transcriptions/methods/create) and should be treated as guidance of input audio content rather than precisely what the model heard. The client can optionally set the language and prompt for transcription, these offer additional guidance to the transcription service.\n',
            }).exactOptional(),
            noise_reduction: z
              .any()
              .refine(
                (val) =>
                  !Array.isArray(val) &&
                  typeof val !== 'string' &&
                  typeof val !== 'number' &&
                  typeof val !== 'boolean',
              )
              .meta({
                description:
                  'Configuration for input audio noise reduction. This can be set to `null` to turn off.\nNoise reduction filters audio added to the input audio buffer before it is sent to VAD and the model.\nFiltering the audio can improve VAD and turn detection accuracy (reducing false positives) and model performance by improving perception of the input audio.\n',
              })
              .exactOptional(),
            turn_detection: RealtimeTurnDetectionSchema.exactOptional(),
          })
          .exactOptional(),
      })
      .meta({ description: 'Configuration for input and output audio.\n' })
      .exactOptional(),
    include: z
      .array(z.literal('item.input_audio_transcription.logprobs'))
      .meta({
        description:
          'Additional fields to include in server outputs.\n\n`item.input_audio_transcription.logprobs`: Include logprobs for input audio transcription.\n',
      })
      .exactOptional(),
  })
  .meta({ description: 'Realtime transcription session object configuration.' })

export type RealtimeTranscriptionSessionCreateRequestGASchema = z.infer<
  typeof RealtimeTranscriptionSessionCreateRequestGASchema
>

export const RealtimeClientEventSessionUpdateSchema = z
  .object({
    event_id: z
      .string()
      .max(512)
      .meta({
        description:
          'Optional client-generated ID used to identify this event. This is an arbitrary string that a client may assign. It will be passed back if there is an error with the event, but the corresponding `session.updated` event will not include it.',
      })
      .exactOptional(),
    type: z
      .literal('session.update')
      .meta({ description: 'The event type, must be `session.update`.' }),
    session: z
      .xor([
        RealtimeSessionCreateRequestGASchema,
        RealtimeTranscriptionSessionCreateRequestGASchema,
      ])
      .meta({
        description:
          'Update the Realtime session. Choose either a realtime\nsession or a transcription session.\n',
      }),
  })
  .meta({
    description:
      'Send this event to update the session’s configuration.\nThe client may send this event at any time to update any field\nexcept for `voice` and `model`. `voice` can be updated only if there have been no other audio outputs yet.\n\nWhen the server receives a `session.update`, it will respond\nwith a `session.updated` event showing the full, effective configuration.\nOnly the fields that are present in the `session.update` are updated. To clear a field like\n`instructions`, pass an empty string. To clear a field like `tools`, pass an empty array.\nTo clear a field like `turn_detection`, pass `null`.\n\nTo turn off input audio noise reduction, send this Realtime event:\n\n```json\n{"type":"session.update","session":{"type":"realtime","audio":{"input":{"noise_reduction":null}}}}\n```\n\nFor a transcription session, use `"type":"transcription"` inside `session`.\nOmitting `audio.input.noise_reduction` from an update leaves its current setting unchanged.\n',
  })

