export const RealtimeResponseSchema = z
  .object({
    id: z
      .string()
      .meta({ description: 'The unique ID of the response, will look like `resp_1234`.' })
      .exactOptional(),
    object: z
      .literal('realtime.response')
      .meta({ description: 'The object type, must be `realtime.response`.' })
      .exactOptional(),
    status: z
      .enum(['completed', 'cancelled', 'failed', 'incomplete', 'in_progress'])
      .meta({
        description:
          'The final status of the response (`completed`, `cancelled`, `failed`, or \n`incomplete`, `in_progress`).\n',
      })
      .exactOptional(),
    status_details: z
      .object({
        type: z
          .enum(['completed', 'cancelled', 'failed', 'incomplete'])
          .meta({
            description:
              'The type of error that caused the response to fail, corresponding \nwith the `status` field (`completed`, `cancelled`, `incomplete`, \n`failed`).\n',
          })
          .exactOptional(),
        reason: z
          .enum(['turn_detected', 'client_cancelled', 'max_output_tokens', 'content_filter'])
          .meta({
            description:
              'The reason the Response did not complete. For a `cancelled` Response,  one of `turn_detected` (the server VAD detected a new start of speech)  or `client_cancelled` (the client sent a cancel event). For an  `incomplete` Response, one of `max_output_tokens` or `content_filter`  (the server-side safety filter activated and cut off the response).\n',
          })
          .exactOptional(),
        error: z
          .object({
            type: z.string().meta({ description: 'The type of error.' }).exactOptional(),
            code: z.string().meta({ description: 'Error code, if any.' }).exactOptional(),
            message: z
              .string()
              .meta({ description: 'A human-readable error message.' })
              .exactOptional(),
          })
          .meta({
            description:
              'A description of the error that caused the response to fail, \npopulated when the `status` is `failed`.\n',
          })
          .exactOptional(),
      })
      .meta({ description: 'Additional details about the status.' })
      .exactOptional(),
    output: z
      .array(RealtimeConversationItemSchema)
      .meta({ description: 'The list of output items generated by the response.' })
      .exactOptional(),
    metadata: MetadataSchema.exactOptional(),
    audio: z
      .object({
        output: z
          .object({
            format: RealtimeAudioFormatsSchema.meta({
              description: 'The format of the output audio.',
            }).exactOptional(),
            voice: VoiceIdsSharedSchema.default('alloy')
              .meta({
                description:
                  'The voice the model uses to respond. Voice cannot be changed during the\nsession once the model has responded with audio at least once. Current\nvoice options are `alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`,\n`shimmer`, `verse`, `marin`, and `cedar`. We recommend `marin` and `cedar` for\nbest quality.\n',
              })
              .exactOptional(),
          })
          .exactOptional(),
      })
      .meta({ description: 'Configuration for audio output.' })
      .exactOptional(),
    usage: z
      .object({
        total_tokens: z
          .int()
          .meta({
            description:
              'The total number of tokens in the Response including input and output \ntext and audio tokens.\n',
          })
          .exactOptional(),
        input_tokens: z
          .int()
          .meta({
            description:
              'The number of input tokens used in the Response, including text and \naudio tokens.\n',
          })
          .exactOptional(),
        output_tokens: z
          .int()
          .meta({
            description:
              'The number of output tokens sent in the Response, including text and \naudio tokens.\n',
          })
          .exactOptional(),
        input_token_details: z
          .object({
            cached_tokens: z
              .int()
              .meta({ description: 'The number of cached tokens used as input for the Response.' })
              .exactOptional(),
            text_tokens: z
              .int()
              .meta({ description: 'The number of text tokens used as input for the Response.' })
              .exactOptional(),
            image_tokens: z
              .int()
              .meta({ description: 'The number of image tokens used as input for the Response.' })
              .exactOptional(),
            audio_tokens: z
              .int()
              .meta({ description: 'The number of audio tokens used as input for the Response.' })
              .exactOptional(),
            cached_tokens_details: z
              .object({
                text_tokens: z
                  .int()
                  .meta({
                    description: 'The number of cached text tokens used as input for the Response.',
                  })
                  .exactOptional(),
                image_tokens: z
                  .int()
                  .meta({
                    description:
                      'The number of cached image tokens used as input for the Response.',
                  })
                  .exactOptional(),
                audio_tokens: z
                  .int()
                  .meta({
                    description:
                      'The number of cached audio tokens used as input for the Response.',
                  })
                  .exactOptional(),
              })
              .meta({
                description: 'Details about the cached tokens used as input for the Response.',
              })
              .exactOptional(),
          })
          .meta({
            description:
              'Details about the input tokens used in the Response. Cached tokens are tokens from previous turns in the conversation that are included as context for the current response. Cached tokens here are counted as a subset of input tokens, meaning input tokens will include cached and uncached tokens.',
          })
          .exactOptional(),
        output_token_details: z
          .object({
            text_tokens: z
              .int()
              .meta({ description: 'The number of text tokens used in the Response.' })
              .exactOptional(),
            audio_tokens: z
              .int()
              .meta({ description: 'The number of audio tokens used in the Response.' })
              .exactOptional(),
          })
          .meta({ description: 'Details about the output tokens used in the Response.' })
          .exactOptional(),
      })
      .meta({
        description:
          'Usage statistics for the Response, this will correspond to billing. A \nRealtime API session will maintain a conversation context and append new \nItems to the Conversation, thus output from previous turns (text and \naudio tokens) will become the input for later turns.\n',
      })
      .exactOptional(),
    conversation_id: z
      .string()
      .meta({
        description:
          'Which conversation the response is added to, determined by the `conversation`\nfield in the `response.create` event. If `auto`, the response will be added to\nthe default conversation and the value of `conversation_id` will be an id like\n`conv_1234`. If `none`, the response will not be added to any conversation and\nthe value of `conversation_id` will be `null`. If responses are being triggered\nautomatically by VAD the response will be added to the default conversation\n',
      })
      .exactOptional(),
    output_modalities: z
      .array(z.enum(['text', 'audio']))
      .meta({
        description:
          'The set of modalities the model used to respond, currently the only possible values are\n`[\\"audio\\"]`, `[\\"text\\"]`. Audio output always include a text transcript. Setting the\noutput to mode `text` will disable audio output from the model.\n',
      })
      .exactOptional(),
    max_output_tokens: z
      .xor([z.int(), z.literal('inf')])
      .meta({
        description:
          'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls, that was used in this response.\n',
      })
      .exactOptional(),
  })
  .meta({ description: 'The response resource.' })

