export const ExpiresAfterParamSchema = z
  .object({
    anchor: z
      .literal('created_at')
      .default('created_at')
      .meta({
        description:
          'Base timestamp used to calculate expiration. Currently fixed to `created_at`.',
      }),
    seconds: z
      .union([z.bigint(), z.number().int(), z.string().regex(/^-?\d+$/)])
      .transform((val) => BigInt(val))
      .pipe(z.int64().min(1n).max(600n))
      .meta({ description: 'Number of seconds after the anchor when the session expires.' }),
  })
  .meta({ description: 'Controls when the session expires relative to an anchor timestamp.' })

export type ExpiresAfterParamSchema = z.infer<typeof ExpiresAfterParamSchema>

