export const SessionAgentResourceSchema = z
  .strictObject({
    id: z.string().min(0).meta({ description: 'The ID of the agent.' }),
    name: z
      .string()
      .min(0)
      .nullable()
      .meta({
        description:
          "The reusable agent's name when the session was created, or null if no name was saved. Later changes to the agent's name do not affect this value.",
      }),
    model: z.string().min(0).meta({ description: 'The model used by the agent.' }),
    reasoning: ReasoningResourceSchema.meta({
      description: "The agent's reasoning configuration.",
    }),
    text: TextResourceSchema.meta({
      description: 'Configuration for text generated by the agent.',
    }),
    service_tier: ServiceTierResourceSchema.meta({
      description: 'The effective service-tier policy for model requests. Defaults to `auto`.',
    }),
    instructions: z
      .string()
      .min(0)
      .nullable()
      .meta({
        description: "Custom instructions appended to the agent's default base instructions.",
      }),
    tools: z
      .array(AgentToolResourceSchema)
      .min(0)
      .max(2000)
      .meta({ description: 'Tools available to the agent.' }),
    multi_agent: MultiAgentConfigResourceSchema.meta({
      description: 'Configuration for creating and coordinating subagents.',
    }),
    compaction: CompactionResourceSchema.meta({
      description: 'The effective context compaction settings.',
    }).exactOptional(),
    experimental: ExperimentalConfigResourceSchema.meta({
      description: 'The effective experimental settings for the agent.',
    }).exactOptional(),
  })
  .meta({ description: 'The effective agent configuration for a session.' })

export type SessionAgentResourceSchema = z.infer<typeof SessionAgentResourceSchema>

