export const SessionResourceSchema = z
  .strictObject({
    prompt_cache_options: z
      .union([PromptCacheOptionsResourceSchema, z.null()])
      .meta({
        description: 'Default prompt cache lifetime for turns in this session, when configured.',
      })
      .exactOptional(),
    review: SessionReviewResourceSchema.meta({
      description:
        'Review applied to eligible actions in this session. Omitted when review is none and automatic review is not enabled. Omission means none.',
    }).exactOptional(),
    spend_control: SessionBudgetControlResourceSchema.meta({
      description:
        'Spending limit and best-effort consumption, in USD cents. The limit is null for an unlimited session. Consumption is null when unavailable.',
    }),
    metadata: z
      .record(z.string(), z.string().min(0))
      .meta({ description: 'Custom string key-value pairs attached to the session.' }),
    id: z.string().min(0).meta({ description: 'The ID of the session.' }),
    object: z
      .literal('agent.session')
      .default('agent.session')
      .meta({ description: 'The object type. Always `agent.session`.' }),
    created_at: z
      .union([z.bigint(), z.number().int(), z.string().regex(/^-?\d+$/)])
      .transform((val) => BigInt(val))
      .pipe(z.int64())
      .meta({ description: 'The Unix timestamp, in seconds, when the session was created.' }),
    last_active_at: z
      .union([z.bigint(), z.number().int(), z.string().regex(/^-?\d+$/)])
      .transform((val) => BigInt(val))
      .pipe(z.int64())
      .meta({ description: 'The Unix timestamp, in seconds, when the session was last active.' }),
    status: SessionStatusResourceSchema.meta({ description: 'The current status of the session.' }),
    required_actions: z
      .array(SessionRequiredActionResourceSchema)
      .min(0)
      .max(2000)
      .meta({ description: 'Actions that must be completed before the session can continue.' }),
    error: z
      .string()
      .min(0)
      .nullable()
      .meta({ description: 'The error that caused the session to fail, if any.' }),
    agent: SessionAgentResourceSchema.meta({ description: 'The agent running in the session.' }),
    environment: EnvironmentResourceSchema.meta({
      description: 'The execution environment for the session.',
    }),
    vault_ids: z
      .array(z.string().min(0))
      .min(0)
      .max(2000)
      .meta({ description: 'The IDs of vaults made available to the session.' }),
    usage: z
      .union([TokenUsageResourceSchema, z.null()])
      .meta({
        description:
          'Best-effort token usage for the session, or null if unknown. Recorded usage may change.',
      }),
  })
  .meta({ description: 'A Managed Agents session.' })

export type SessionResourceSchema = z.infer<typeof SessionResourceSchema>

