export const SessionEnvironmentStateResourceSchema = z
  .strictObject({
    id: z.string().min(0).meta({ description: 'The public ID of the environment.' }),
    type: z.string().min(0).meta({ description: 'The environment type.' }),
    status: SessionEnvironmentStatusResourceSchema.meta({
      description: "The environment's connection status.",
    }),
    error: z
      .union([SessionEnvironmentErrorResourceSchema, z.null()])
      .meta({ description: 'The error reported while preparing the environment, if any.' }),
  })
  .meta({ description: 'The current state of a session environment.' })

export type SessionEnvironmentStateResourceSchema = z.infer<
  typeof SessionEnvironmentStateResourceSchema
>

export const SessionEventAgentSessionEnvironmentReadySchema = z
  .strictObject({
    type: z
      .literal('agent.session.environment.ready')
      .default('agent.session.environment.ready')
      .meta({ description: 'The type of the object. Always `agent.session.environment.ready`.' }),
    event_id: z.string().min(0).meta({ description: 'The unique ID of the event.' }),
    session_id: z
      .string()
      .min(0)
      .meta({ description: 'The ID of the session associated with the event.' }),
    turn_id: z
      .string()
      .min(0)
      .nullable()
      .meta({ description: 'The ID of the turn associated with the event, when applicable.' }),
    environment: SessionEnvironmentStateResourceSchema.meta({
      description: 'The current environment state.',
    }),
    obfuscation: z
      .string()
      .min(0)
      .meta({
        description: 'Random alphanumeric padding. Present when stream obfuscation is enabled.',
      })
      .exactOptional(),
  })
  .meta({ description: 'Emitted when a hosted session environment is ready to connect.' })

export type SessionEventAgentSessionEnvironmentReadySchema = z.infer<
  typeof SessionEventAgentSessionEnvironmentReadySchema
>

