export const SessionEventAgentSessionEnvironmentResetSchema = z
  .strictObject({
    type: z
      .literal('agent.session.environment.reset')
      .default('agent.session.environment.reset')
      .meta({ description: 'The type of the object. Always `agent.session.environment.reset`.' }),
    event_id: z.string().min(0).meta({ description: 'The unique ID of the event.' }),
    session_id: z
      .string()
      .min(0)
      .meta({ description: 'The ID of the session associated with the event.' }),
    turn_id: z
      .string()
      .min(0)
      .nullable()
      .meta({ description: 'The associated turn, when applicable.' }),
    environment_id: z
      .string()
      .min(0)
      .meta({ description: 'The stable environment ID, retained across sandbox replacements.' }),
    reset_count: z
      .union([z.bigint(), z.number().int(), z.string().regex(/^-?\d+$/)])
      .transform((val) => BigInt(val))
      .pipe(z.int64().min(0n))
      .meta({
        description:
          'Monotonically increasing reset number. Repeated notifications share this number.',
      }),
    obfuscation: z
      .string()
      .min(0)
      .meta({
        description: 'Random alphanumeric padding. Present when stream obfuscation is enabled.',
      })
      .exactOptional(),
  })
  .meta({
    description:
      "Emitted after a hosted sandbox is replaced. Conversation history survives; changes to the previous sandbox's files and processes do not.",
  })

export type SessionEventAgentSessionEnvironmentResetSchema = z.infer<
  typeof SessionEventAgentSessionEnvironmentResetSchema
>

export const SessionEventAgentOutputCommandExecutionOutputDeltaSchema = z
  .strictObject({
    type: z
      .literal('agent.output.command_execution_output.delta')
      .default('agent.output.command_execution_output.delta')
      .meta({
        description:
          'The type of the object. Always `agent.output.command_execution_output.delta`.',
      }),
    event_id: z.string().min(0).meta({ description: 'The unique ID of the event.' }),
    session_id: z
      .string()
      .min(0)
      .meta({ description: 'The ID of the session associated with the event.' }),
    turn_id: z
      .string()
      .min(0)
      .nullable()
      .meta({ description: 'The ID of the turn associated with the event, when applicable.' }),
    item_id: z.string().min(0).meta({ description: 'The ID of the command execution item.' }),
    output_index: z
      .union([z.bigint(), z.number().int(), z.string().regex(/^-?\d+$/)])
      .transform((val) => BigInt(val))
      .pipe(z.int64().min(0n).max(4294967295n))
      .meta({ description: 'The index of the item in the turn output.' }),
    delta: z.string().min(0).meta({ description: 'The output text that was appended.' }),
    obfuscation: z
      .string()
      .min(0)
      .meta({
        description: 'Random alphanumeric padding. Present when stream obfuscation is enabled.',
      })
      .exactOptional(),
  })
  .meta({ description: 'Emitted when command execution produces an output delta.' })

export type SessionEventAgentOutputCommandExecutionOutputDeltaSchema = z.infer<
  typeof SessionEventAgentOutputCommandExecutionOutputDeltaSchema
>

