export const BetaComparisonFilterSchema = z
  .strictObject({
    type: z
      .enum(['eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'in', 'nin'])
      .default('eq')
      .meta({
        description:
          'Specifies the comparison operator: `eq`, `ne`, `gt`, `gte`, `lt`, `lte`, `in`, `nin`.\n- `eq`: equals\n- `ne`: not equal\n- `gt`: greater than\n- `gte`: greater than or equal\n- `lt`: less than\n- `lte`: less than or equal\n- `in`: in\n- `nin`: not in\n',
      }),
    key: z.string().meta({ description: 'The key to compare against the value.' }),
    value: z
      .xor([z.string(), z.number(), z.boolean(), z.array(z.xor([z.string(), z.number()]))])
      .meta({
        description:
          'The value to compare against the attribute key; supports string, number, or boolean types.',
      }),
  })
  .meta({
    description:
      'A filter used to compare a specified attribute key to a given value using a defined comparison operation.\n',
  })

export type BetaComparisonFilterSchema = z.infer<typeof BetaComparisonFilterSchema>

type BetaCompoundFilterType = {
  type: 'and' | 'or'
  filters: (z.infer<typeof BetaComparisonFilterSchema> | BetaCompoundFilterType)[]
}

export const BetaCompoundFilterSchema: z.ZodType<BetaCompoundFilterType> = z
  .strictObject({
    type: z.enum(['and', 'or']).meta({ description: 'Type of operation: `and` or `or`.' }),
    filters: z
      .array(
        z.xor([
          z.intersection(
            BetaComparisonFilterSchema,
            z.object({ type: z.literal('BetaComparisonFilter') }),
          ),
          z.intersection(
            z.lazy(() => BetaCompoundFilterSchema),
            z.object({ type: z.literal('BetaCompoundFilter') }),
          ),
        ]),
      )
      .meta({
        description:
          'Array of filters to combine. Items can be `ComparisonFilter` or `CompoundFilter`.',
      }),
  })
  .meta({ description: 'Combine multiple filters using `and` or `or`.' })

export type BetaCompoundFilterSchema = z.infer<typeof BetaCompoundFilterSchema>

export const BetaFiltersSchema = z.union([BetaComparisonFilterSchema, BetaCompoundFilterSchema])

export type BetaFiltersSchema = z.infer<typeof BetaFiltersSchema>

